create extension if not exists "pgcrypto";
create table if not exists public.admin_users(user_id uuid primary key references auth.users(id) on delete cascade,display_name text,created_at timestamptz not null default now());
create table if not exists public.committee_members(id uuid primary key default gen_random_uuid(),serial text,position text not null,name text not null,phone text,email text,department text,photo_url text,leader boolean not null default false,active boolean not null default true,sort_order integer not null default 999,created_at timestamptz not null default now());
create table if not exists public.events(id uuid primary key default gen_random_uuid(),title text not null,description text,starts_at timestamptz not null,location text,poster_url text,published boolean not null default true,created_at timestamptz not null default now());
create table if not exists public.media_items(id uuid primary key default gen_random_uuid(),title text not null,media_type text not null check(media_type in('photo','video')),thumbnail_url text not null,destination_url text,featured boolean not null default false,published boolean not null default true,published_at timestamptz not null default now(),created_at timestamptz not null default now());
create table if not exists public.member_applications(id uuid primary key default gen_random_uuid(),full_name text not null,eu_id text not null unique,department text not null,address text not null,date_of_birth date not null,blood_group text not null,email text not null,phone_whatsapp text not null,skills text not null,reason text not null,bkash_sender text not null,bkash_transaction_id text not null unique,registration_fee integer not null default 100 check(registration_fee=100),status text not null default 'payment_submitted' check(status in('payment_submitted','verified','approved','rejected')),created_at timestamptz not null default now());
alter table public.admin_users enable row level security;alter table public.committee_members enable row level security;alter table public.events enable row level security;alter table public.media_items enable row level security;alter table public.member_applications enable row level security;
create policy "Public committee" on public.committee_members for select using(active=true);create policy "Public events" on public.events for select using(published=true);create policy "Public media" on public.media_items for select using(published=true);create policy "Public application submit" on public.member_applications for insert with check(status='payment_submitted' and registration_fee=100);create policy "Own admin record" on public.admin_users for select using(auth.uid()=user_id);create policy "Admin committee" on public.committee_members for all using(exists(select 1 from public.admin_users a where a.user_id=auth.uid())) with check(exists(select 1 from public.admin_users a where a.user_id=auth.uid()));create policy "Admin events" on public.events for all using(exists(select 1 from public.admin_users a where a.user_id=auth.uid())) with check(exists(select 1 from public.admin_users a where a.user_id=auth.uid()));create policy "Admin media" on public.media_items for all using(exists(select 1 from public.admin_users a where a.user_id=auth.uid())) with check(exists(select 1 from public.admin_users a where a.user_id=auth.uid()));create policy "Admin applications read" on public.member_applications for select using(exists(select 1 from public.admin_users a where a.user_id=auth.uid()));create policy "Admin applications update" on public.member_applications for update using(exists(select 1 from public.admin_users a where a.user_id=auth.uid()));
insert into storage.buckets(id,name,public) values('vac-media','vac-media',true) on conflict(id) do update set public=excluded.public;create policy "Public VAC media" on storage.objects for select using(bucket_id='vac-media');create policy "Admin VAC media insert" on storage.objects for insert with check(bucket_id='vac-media' and exists(select 1 from public.admin_users a where a.user_id=auth.uid()));create policy "Admin VAC media update" on storage.objects for update using(bucket_id='vac-media' and exists(select 1 from public.admin_users a where a.user_id=auth.uid()));create policy "Admin VAC media delete" on storage.objects for delete using(bucket_id='vac-media' and exists(select 1 from public.admin_users a where a.user_id=auth.uid()));
